import{_ as i,o as l,c as t,ag as e}from"./chunks/framework.D9ghT4bC.js";const v=JSON.parse('{"title":"UncivCN 更新日志","description":"","frontmatter":{"title":"UncivCN 更新日志"},"headers":[],"relativePath":"zh/UncivCN/Changelog.md","filePath":"zh/UncivCN/Changelog.md"}'),r={name:"zh/UncivCN/Changelog.md"};function o(n,a,d,u,h,c){return l(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="uncivcn-更新日志" tabindex="-1">UncivCN 更新日志 <a class="header-anchor" href="#uncivcn-更新日志" aria-label="Permalink to &quot;UncivCN 更新日志&quot;">​</a></h1><p>版本号规则：上游版本 + CN 子版本号（<code>.1</code>、<code>.2</code>、<code>.3</code>…，同一上游版本可发多个 CN 子版本，如 4.20.8.1 → 4.20.8.4；跟进新上游后从 <code>.1</code> 重新开始，如 4.21.5 → 4.21.5.1）。</p><p>详细历史记录见 <a href="/Unciv/zh/UncivCN/Changelog.html">UncivCN 更新日志（社区归档）</a>。</p><h2 id="v4-21-5-3-build-1244" tabindex="-1">v4.21.5.3（build 1244） <a class="header-anchor" href="#v4-21-5-3-build-1244" aria-label="Permalink to &quot;v4.21.5.3（build 1244）&quot;">​</a></h2><ul><li>修复 CI 测试失败：13 行翻译模板缺末尾空格（TranslationTests 挂掉）；测试模组 testMOD / testMapScript 此前被 .gitignore 忽略，导致 CI 上 Lua 脚本与合并动作测试大量失败，现已纳入版本库并补充 testMOD/jsons/Buildings.json</li><li>Deploy 工作流不再向 Discord 推送发布通知（GitHub Release 上传保留）</li></ul><h2 id="v4-21-5-2-build-1243" tabindex="-1">v4.21.5.2（build 1243） <a class="header-anchor" href="#v4-21-5-2-build-1243" aria-label="Permalink to &quot;v4.21.5.2（build 1243）&quot;">​</a></h2><ul><li>官方文档站上线：全新 VitePress 文档站（替换 mkdocs），支持中文全文搜索、中英文一键切换、unique 列表一键复制 <ul><li>英文区完整复用上游文档；中文区为完整翻译镜像（Modders / Developers / Translating / Other 等全部页面）</li><li>新增 UncivCN 专区（分支介绍 / 新特性 / 更新日志 / 差异对照 / 代码规范 / 轮询联机）与社区内容区（原版攻略 / 模组专区 / 源码分析 / 上游更新日志），均提供中英双语</li></ul></li><li>unique 说明文档中文化：新增 docDescriptionZh 机制，模组制作者可在文档站查看中文 unique 说明</li><li>构建与发布流程适配：APK 签名本地化（zipalign + apksigner V3）、产物命名 UncivCN；新增签名回归 CI</li></ul><h2 id="v4-21-5-1-build-1242-—-当前版本" tabindex="-1">v4.21.5.1（build 1242）— 当前版本 <a class="header-anchor" href="#v4-21-5-1-build-1242-—-当前版本" aria-label="Permalink to &quot;v4.21.5.1（build 1242）— 当前版本&quot;">​</a></h2><ul><li>合并上游 4.21.5（AI 金币/战争逻辑修复、CPU 性能优化、城市邦开局优化等，详见上游 <a href="https://github.com/AutumnPizazz/Unciv/blob/UncivCN/changelog.md" target="_blank" rel="noreferrer">changelog.md</a>）</li><li>撤销自带 UCCC 模组改动，游戏本体不再打包任何模组</li><li>新增新建游戏设置导出/导入剪贴板功能</li><li>调整人口锁地按钮逻辑</li><li>修复统计显示级联 bug，与上游 master 对齐</li></ul><h2 id="v4-21-0-2-2026-8-1" tabindex="-1">v4.21.0.2（2026.8.1） <a class="header-anchor" href="#v4-21-0-2-2026-8-1" aria-label="Permalink to &quot;v4.21.0.2（2026.8.1）&quot;">​</a></h2><ul><li>修复 UCCC 模组部分 bug</li></ul><h2 id="v4-21-0-1-2026-8-1" tabindex="-1">v4.21.0.1（2026.8.1） <a class="header-anchor" href="#v4-21-0-1-2026-8-1" aria-label="Permalink to &quot;v4.21.0.1（2026.8.1）&quot;">​</a></h2><ul><li>跟进 Unciv 原版近期更新（含对称/镜像地图、统计面板等上游合入功能）</li><li>由于与上游对胜利面板均作类似功能改动，回退「禁用文明积分面板时同步禁用实验性统计面板」功能，以上游为准</li><li>补全缺失的中文本地化</li><li>联机默认服务器改为 <code>http://sp.unciv.cn:30123</code></li><li>新增人口自动锁定快捷按钮（城市屏幕右下角「自动锁定」，永久切换不锁/锁人口）</li><li>自带 UCCC 模组</li><li>随机数可通过读档改变功能联机时不再可用</li></ul><h2 id="v4-20-17-2-2026-7-12" tabindex="-1">v4.20.17.2（2026.7.12） <a class="header-anchor" href="#v4-20-17-2-2026-7-12" aria-label="Permalink to &quot;v4.20.17.2（2026.7.12）&quot;">​</a></h2><ul><li>新增单位钉、地图钉功能（详见 [新特性./Features#单位钉--地图钉420172)）</li><li>取消旋转对称地图对半径的奇偶限制</li><li>禁用文明积分面板时同步禁用实验性统计面板</li><li>实现游戏版本兼容性隔离（旧版无法加载新版存档）</li><li>训练移民等食物→产能单位时避免市民饿死</li></ul><h2 id="v4-20-17-1-2026-7-4" tabindex="-1">v4.20.17.1（2026.7.4） <a class="header-anchor" href="#v4-20-17-1-2026-7-4" aria-label="Permalink to &quot;v4.20.17.1（2026.7.4）&quot;">​</a></h2><ul><li>跟进 Unciv 原版一个多月的更新</li></ul><h2 id="v4-20-8-4-2026-5-26" tabindex="-1">v4.20.8.4（2026.5.26） <a class="header-anchor" href="#v4-20-8-4-2026-5-26" aria-label="Permalink to &quot;v4.20.8.4（2026.5.26）&quot;">​</a></h2><ul><li>原生模组检查器可筛查模组的 Lua 错误</li><li>轮询联机功能可查看其他玩家的在线状态</li></ul><h2 id="v4-20-8-3-2026-5-23" tabindex="-1">v4.20.8.3（2026.5.23） <a class="header-anchor" href="#v4-20-8-3-2026-5-23" aria-label="Permalink to &quot;v4.20.8.3（2026.5.23）&quot;">​</a></h2><ul><li>增强 Lua 系统</li><li>event 可挂载 Lua</li></ul><h2 id="v4-20-8-2-2026-5-22" tabindex="-1">v4.20.8.2（2026.5.22） <a class="header-anchor" href="#v4-20-8-2-2026-5-22" aria-label="Permalink to &quot;v4.20.8.2（2026.5.22）&quot;">​</a></h2><ul><li>模组支持 <a href="/Unciv/zh/Modders/Lua-Modding.html">Lua 脚本</a></li><li>修复「众神与国王」精英教育政策不送伟人的 bug</li><li>Amount 参数兼容 Countables，新增多个 Countables 参数类型</li><li>修复 TRY_INJECT 单位时将造价覆盖为 0 的 bug</li></ul><h2 id="v4-20-8-1-2026-5-21" tabindex="-1">v4.20.8.1（2026.5.21） <a class="header-anchor" href="#v4-20-8-1-2026-5-21" aria-label="Permalink to &quot;v4.20.8.1（2026.5.21）&quot;">​</a></h2><ul><li>重磅更新！新增 [轮询联机功能./Polling-multiplayer)</li></ul><h2 id="v4-20-7-4-2026-5-19" tabindex="-1">v4.20.7.4（2026.5.19） <a class="header-anchor" href="#v4-20-7-4-2026-5-19" aria-label="Permalink to &quot;v4.20.7.4（2026.5.19）&quot;">​</a></h2><ul><li>中心对称地图现在让资源数量也对称分布</li></ul><h2 id="v4-20-7-3-2026-5-19" tabindex="-1">v4.20.7.3（2026.5.19） <a class="header-anchor" href="#v4-20-7-3-2026-5-19" aria-label="Permalink to &quot;v4.20.7.3（2026.5.19）&quot;">​</a></h2><ul><li>扩展模组 JSON 系统，详见 <a href="/Unciv/zh/Modders/Mod-file-structure/6-MergeActions.html">MergeAction 教程</a></li></ul><hr><h2 id="v4-20-7-2" tabindex="-1">v4.20.7.2 <a class="header-anchor" href="#v4-20-7-2" aria-label="Permalink to &quot;v4.20.7.2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.19</p><ul><li>安卓端安装包不再自带模组 CoeHarMod/和合共生</li><li>新增三种镜像地图模式，按两瓣/三瓣/六瓣中心对称分布</li></ul><h2 id="v4-20-6-3" tabindex="-1">v4.20.6.3 <a class="header-anchor" href="#v4-20-6-3" aria-label="Permalink to &quot;v4.20.6.3&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.17</p><ul><li>新增模组特性：</li></ul><table tabindex="0"><thead><tr><th>英文原文</th><th>中文释义</th></tr></thead><tbody><tr><td><code>Hidden from city screen</code></td><td>不再显示在城市面板中</td></tr><tr><td><code>Can be built [amount] times in each city</code></td><td>可以在单个城市中重复建造[amount]次</td></tr></tbody></table><h2 id="v4-20-6-1" tabindex="-1">v4.20.6.1 <a class="header-anchor" href="#v4-20-6-1" aria-label="Permalink to &quot;v4.20.6.1&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.16</p><ul><li>同步两个月来 Unciv 原版的更新内容</li><li>将前几个版本对随机性结果可变性的改动收束到设置页面，可选择是否启用</li></ul><h2 id="v4-19-16-2" tabindex="-1">v4.19.16.2 <a class="header-anchor" href="#v4-19-16-2" aria-label="Permalink to &quot;v4.19.16.2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.3.2</p><ul><li>远古遗迹产出随机性结果可以通过读档重载改变</li></ul><h2 id="v4-19-16-1" tabindex="-1">v4.19.16.1 <a class="header-anchor" href="#v4-19-16-1" aria-label="Permalink to &quot;v4.19.16.1&quot;">​</a></h2><p><strong>发布日期</strong>：2026.3.1</p><ul><li>城邦任务随机性结果可以通过读档重载改变</li></ul><h2 id="v4-19-15-cn2" tabindex="-1">v4.19.15-cn2 <a class="header-anchor" href="#v4-19-15-cn2" aria-label="Permalink to &quot;v4.19.15-cn2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.2.28</p><ul><li>新增模组特性：</li></ul><table tabindex="0"><thead><tr><th>英文原文</th><th>中文释义</th></tr></thead><tbody><tr><td><code>Attacks also target [mapUnitFilter] units within [positiveAmount] tiles</code></td><td>攻击也会同时攻击 [positiveAmount] 格内满足 [mapUnitFilter] 的单位</td></tr><tr><td><code>Attacks also target [mapUnitFilter] units within [positiveAmount] tiles, with damage decreasing by distance</code></td><td>攻击也会同时攻击 [positiveAmount] 格内满足 [mapUnitFilter] 的单位，伤害随距离递减</td></tr><tr><td><code>Takes [relativeAmount]% damage from own area attacks</code></td><td>受到自身范围攻击时，仅承受 [relativeAmount]% 的伤害</td></tr><tr><td><code>Takes [relativeAmount]% counter damage from each unit hit by its area attacks</code></td><td>其范围攻击每击中一个单位，自身就会承受该单位 [relativeAmount]% 的反击伤害</td></tr></tbody></table><ul><li>添加统计面板数据导出为 csv 表格的功能</li></ul><h2 id="v4-19-15" tabindex="-1">v4.19.15 <a class="header-anchor" href="#v4-19-15" aria-label="Permalink to &quot;v4.19.15&quot;">​</a></h2><p><strong>发布日期</strong>：2026.2.26</p><ul><li>为安卓端安装包加入内置模组 <a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">CoeHarMod/和合共生</a></li><li>允许相邻城市切换地块，需要在模组的 ModOptions.json 文件中声明 uniques &quot;Allow cities to claim tiles&quot;</li></ul>',54)])])}const b=i(r,[["render",o]]);export{v as __pageData,b as default};
